Output15Using String Conversion A number is made up of digits, and when convert it into a string, each digit becomes a character that can be accessed directly by going through each character one by one and converting it back to a digit, Let’s take n = 1234 Convert number to string → "1234" Start with first character '1' Convert to digit -> Sum = 1  Move to next character '2' Convert to digit -> 2, Sum = 1 + 2 = 3  Next character '3' Convert to digit -> 3, Sum = 3 + 3 = 6  Next character '4' Convert to digit -> 4, sum = 6 + 4 = 10  No more characters left -> stop Sum of digits = 10Note: This method is especially useful when the number is too large to fit in standard integer types.
            C++

    #include <iostream>
#include <string>
using namespace std;

// Function to calculate sum of digits using string conversion

int sumOfDigits(int n) {

    // Convert number to string
    string s = to_string(n);  
    int sum = 0;

    // Loop through each character, convert to digit, and add to sum
    for (char ch : s) {
        sum += ch - '0';
    }
    return sum;
}

int main() {
    int n = 12345;
    cout << sumOfDigits(n) << endl;
    return 0;
}


