    char s[20];
    sprintf(s, "%d", n);
    int sum = 0;

    // Loop through each character, convert
    // to digit, and add to sum
    for (int i = 0; i < strlen(s); i++) {
        sum += s[i] - '0';
    }

    return sum;
}

